#include <inttypes.h>
#include <limits.h>
#include <stddef.h>
#include <stdint.h>
#include <stdio.h>

struct Record {
    char tag;
    int value;
};

int main(void)
{
    const size_t record_size = sizeof(struct Record);
    const size_t value_offset = offsetof(struct Record, value);

#if defined(UINT32_MAX)
    {
        const uint32_t count = UINT32_C(42);
        printf("Count: %" PRIu32 "\n", count);
    }
#else
    puts("This implementation has no exact 32-bit unsigned integer type.");
#endif

    printf("Record size: %zu; value offset: %zu\n",
           record_size, value_offset);
    printf("INT_MAX: %d; SIZE_MAX: %zu\n", INT_MAX, (size_t)SIZE_MAX);
    return 0;
}

#include <ctype.h>
#include <errno.h>
#include <stdio.h>
#include <stdlib.h>

int main(int argc, char *argv[])
{
    char *end = NULL;
    long value;

    if (argc != 2) {
        fprintf(stderr, "Usage: %s integer\n", argv[0]);
        return EXIT_FAILURE;
    }

    errno = 0;
    value = strtol(argv[1], &end, 10);
    if (end == argv[1] || errno == ERANGE) {
        fputs("Invalid or out-of-range integer.\n", stderr);
        return EXIT_FAILURE;
    }
    while (isspace((unsigned char)*end) != 0) {
        ++end;
    }
    if (*end != '\0') {
        fputs("Unexpected trailing characters.\n", stderr);
        return EXIT_FAILURE;
    }

    printf("Parsed value: %ld\n", value);
    return EXIT_SUCCESS;
}
